answers.workaround:
There is a workaround and it's _extremely_ gross: to traverse the editor node tree manually until you've found the `EditorInspector` you're looking for. I've pasted the code we have in our project below just to indicate how dirty we're playing here:

```gdscript
func _find_and_subscribe_to_property_changes_for_wave_label(c: Container, label: Label, wave: Wave) -> void:
	if _wave_found:
		return

	for c2 in c.get_children():
		if c2 is EditorInspector:
			var ei: EditorInspector = (c2 as EditorInspector)
			var eo: Object = ei.get_edited_object()
			if eo is Wave:
				var w: Wave = eo as Wave
				if w == wave:
					var callable: Callable = update_label.bindv([label, wave])
					if ei.property_edited.is_connected(callable):
						# disconnect and reconnect so that no callable's to old labels remain
						ei.property_edited.disconnect(callable)
					ei.property_edited.connect(callable)
					_wave_found = true
					return

		if c2 is Container:
			_find_and_subscribe_to_property_changes_for_wave_label(c2, label, wave)
```
